namespace TScan.Web.Models;\n\npublic class Order\n{\n    public Guid Id { get; set; }\n    public Guid MatterId { get; set; }\n    public Guid FirmId { get; set; }\n    public Guid CreatedByUserId { get; set; }\n    public string OrderNumber { get; set; } = string.Empty; // Auto-generated\n    public string OrderType { get; set; } = string.Empty; // Medical Records, Court Documents, etc.\n    public string ProviderName { get; set; } = string.Empty;\n    public string? ProviderAddress { get; set; }\n    public string? ProviderContact { get; set; }\n    public string RecordType { get; set; } = string.Empty;\n    public DateTime? DateRangeStart { get; set; }\n    public DateTime? DateRangeEnd { get; set; }\n    public string? SpecialInstructions { get; set; }\n    public string? BillingReference { get; set; }\n    public string Status { get; set; } = "Submitted"; // Submitted, Processing, Completed, Cancelled\n    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;\n    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;\n    public DateTime? SubmittedAt { get; set; }\n\n    // Navigation\n    public virtual Matter? Matter { get; set; }\n    public virtual Firm? Firm { get; set; }\n    public virtual ApplicationUser? CreatedByUser { get; set; }\n    public virtual ICollection<Document> Documents { get; set; } = new List<Document>();\n}\n